    SurahModel(number: 20, nameArabic: 'سُورَةُ طَهَ', nameUrdu: 'سورۃ طہٰ', nameEnglish: 'Surah Ta-Ha', versesCount: 135, revelationType: 'مکی (Meccan)', virtueUrdu: 'حضرت موسیٰ علیہ السلام کا واقعہ اور دل کی آسانی کی دعا۔', virtueEnglish: 'Contains Prophet Moses\'s famous supplication for ease of speech.', verses: [SurahVerseModel(number: 25, arabic: 'رَبِّ ٱشْرَحْ لِى صَدْرِى', urduTranslation: 'اے میرے رب! میرے لیے میرا سینہ کھول دے۔', englishTranslation: 'My Lord, expand for me my breast.')]),
    SurahModel(number: 21, nameArabic: 'سُورَةُ ٱلْأَنبِيَآءِ', nameUrdu: 'سورۃ الانبیاء', nameEnglish: 'Surah Al-Anbiya', versesCount: 112, revelationType: 'مکی (Meccan)', virtueUrdu: 'انبیاء کرام کی دعائیں، بالخصوص حضرت یونس علیہ السلام کی آیت کریمہ۔', virtueEnglish: 'Contains Ayat-ul-Karima, the powerful prayer for relief from anxiety.', verses: [SurahVerseModel(number: 87, arabic: 'لَآ إِلَـٰهَ إِلَّآ أَنتَ سُبْحَـٰنَكَ إِنِّى كُنتُ مِنَ ٱلظَّـٰلِمِينَ', urduTranslation: 'تیرے سوا کوئی معبود نہیں، تو پاک ہے، بیشک میں ہی ظالموں میں سے تھا۔', englishTranslation: 'There is no deity except You; exalted are You. Indeed, I have been of the wrongdoers.')]),
    SurahModel(number: 22, nameArabic: 'سُورَةُ ٱلْحَجِّ', nameUrdu: 'سورۃ الحج', nameEnglish: 'Surah Al-Hajj', versesCount: 78, revelationType: 'مدنی (Medinan)', virtueUrdu: 'حج کی عظمت اور قیامت کے ہولناک مناظر کا بیان۔', virtueEnglish: 'Highlights the pilgrimage to Mecca and Day of Judgment.', verses: [SurahVerseModel(number: 77, arabic: 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ ٱرْكَعُوا۟ وَٱسْجُدُوا۟ وَٱعْبُدُوا۟ رَبَّكُمْ...', urduTranslation: 'اے ایمان والو! رکوع کرو، سجدہ کرو اور اپنے رب کی عبادت کرو...', englishTranslation: 'O you who have believed, bow and prostrate and worship your Lord...')]),
    SurahModel(number: 23, nameArabic: 'سُورَةُ ٱلْمُؤْمِنُونَ', nameUrdu: 'سورۃ المؤمنون', nameEnglish: 'Surah Al-Mu\'minun', versesCount: 118, revelationType: 'مکی (Meccan)', virtueUrdu: 'کامیاب اور جنتی مومنوں کی اوصاف اور خوبیوں کا بیان۔', virtueEnglish: 'Outlines the noble qualities of successful believers.', verses: [SurahVerseModel(number: 1, arabic: 'قَدْ أَفْلَحَ ٱلْمُؤْمِنُونَ', urduTranslation: 'بیشک ایمان والے کامیاب ہو گئے۔', englishTranslation: 'Certainly will the believers have succeeded:')]),
    SurahModel(number: 24, nameArabic: 'سُورَةُ ٱلنُّورِ', nameUrdu: 'سورۃ النور', nameEnglish: 'Surah An-Nur', versesCount: 64, revelationType: 'مدنی (Medinan)', virtueUrdu: 'حجاب، پاکدامنی اور اللہ کے نور کی بے مثال آیت پر مشتمل سورۃ۔', virtueEnglish: 'Contains the magnificent Verse of Light and family modesty guidelines.', verses: [SurahVerseModel(number: 35, arabic: 'ٱللَّهُ نُورُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۚ...', urduTranslation: 'اللہ آسمانوں اور زمین کا نور ہے...', englishTranslation: 'Allah is the Light of the heavens and the earth...')]),
    SurahModel(number: 25, nameArabic: 'سُورَةُ ٱلْفُرْقَانِ', nameUrdu: 'سورۃ الفرقان', nameEnglish: 'Surah Al-Furqan', versesCount: 77, revelationType: 'مکی (Meccan)', virtueUrdu: 'حق اور باطل میں فرق اور عباد الرحمٰن (رحمٰن کے بندوں) کی صفات۔', virtueEnglish: 'Distinguishes truth from falsehood and describes the Servants of the Merciful.', verses: [SurahVerseModel(number: 63, arabic: 'وَعِبَادُ ٱلرَّحْمَـٰنِ ٱلَّذِينَ يَمْشُونَ عَلَى ٱلْأَرْضِ هَوْنًۭا...', urduTranslation: 'اور رحمٰن کے بندے وہ ہیں جو زمین پر عاجزی سے چلتے ہیں...', englishTranslation: 'And the servants of the Most Merciful are those who walk upon the earth easily...')]),
    SurahModel(number: 26, nameArabic: 'سُورَةُ ٱلشُّعَرَآءِ', nameUrdu: 'سورۃ الشعراء', nameEnglish: 'Surah Ash-Shu\'ara', versesCount: 227, revelationType: 'مکی (Meccan)', virtueUrdu: 'انبیاء کرام کی تبلیغ اور حق پر ثابت قدمی کے واقعات۔', virtueEnglish: 'Recounts prophetic mission and patience with opponents.', verses: [SurahVerseModel(number: 80, arabic: 'وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ', urduTranslation: 'اور جب میں بیمار ہوتا ہوں تو وہی مجھے شفا دیتا ہے۔', englishTranslation: 'And when I am ill, it is He who cures me.')]),
    SurahModel(number: 27, nameArabic: 'سُورَةُ ٱلنَّمْلِ', nameUrdu: 'سورۃ النمل', nameEnglish: 'Surah An-Naml', versesCount: 93, revelationType: 'مکی (Meccan)', virtueUrdu: 'حضرت سلیمان علیہ السلام، ملکہ سبا اور پرندوں و چیونٹیوں کے واقعات۔', virtueEnglish: 'The Kingdom of Prophet Solomon and the Queen of Sheba.', verses: [SurahVerseModel(number: 19, arabic: 'رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ...', urduTranslation: 'اے میرے رب! مجھے توفیق دے کہ میں تیری اس نعمت کا شکر ادا کروں...', englishTranslation: 'My Lord, enable me to be grateful for Your favor...')]),
    SurahModel(number: 28, nameArabic: 'سُورَةُ ٱلْقَصَصِ', nameUrdu: 'سورۃ القصص', nameEnglish: 'Surah Al-Qasas', versesCount: 88, revelationType: 'مکی (Meccan)', virtueUrdu: 'حضرت موسیٰ علیہ السلام کی پیدائش اور قارون کے عبرتناک انجام کا بیان۔', virtueEnglish: 'The early life of Moses and warning against Qarun\'s pride.', verses: [SurahVerseModel(number: 24, arabic: 'رَبِّ إِنِّى لِمَآ أَنزَلْتَ إِلَىَّ مِنْ خَيْرٍۢ فَقِيرٌۭ', urduTranslation: 'اے میرے رب! تو جو بھی بھلائی مجھ پر نازل فرمائے میں اس کا محتاج ہوں۔', englishTranslation: 'My Lord, indeed I am, for whatever good You would send down to me, in need.')]),
    SurahModel(number: 29, nameArabic: 'سُورَةُ ٱلْعَنكَبُوتِ', nameUrdu: 'سورۃ العنکبوت', nameEnglish: 'Surah Al-Ankabut', versesCount: 69, revelationType: 'مکی (Meccan)', virtueUrdu: 'ایمان والوں کی آزمائش اور باطل سہاروں کی حقیقت کا بیان۔', virtueEnglish: 'Highlights trials of faith and fragility of worldly reliance.', verses: [SurahVerseModel(number: 45, arabic: 'إِنَّ ٱلصَّلَوٰةَ تَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ...', urduTranslation: 'بیشک نماز بے حیائی اور برے کاموں سے روکتی ہے...', englishTranslation: 'Indeed, prayer prohibits immorality and wrongdoing...')]),
    SurahModel(number: 30, nameArabic: 'سُورَةُ ٱلرُّومِ', nameUrdu: 'سورۃ الروم', nameEnglish: 'Surah Ar-Rum', versesCount: 60, revelationType: 'مکی (Meccan)', virtueUrdu: 'کائنات میں اللہ کی نشانیوں اور فتح کی پیشن گوئی کا بیان۔', virtueEnglish: 'Contains signs of creation and prophecy of divine victory.', verses: [SurahVerseModel(number: 21, arabic: 'وَمِنْ ءَايَـٰتِهِۦٓ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَٰجًۭا لِّتَسْكُنُوٓا۟ إِلَيْهَا...', urduTranslation: 'اور اس کی نشانیوں میں سے ہے کہ اس نے تمہارے لیے تمہی میں سے جوڑے پیدا کیے...', englishTranslation: 'And of His signs is that He created for you from yourselves mates...')]),
    SurahModel(number: 31, nameArabic: 'سُورَةُ لُقْمَانَ', nameUrdu: 'سورۃ لقمان', nameEnglish: 'Surah Luqman', versesCount: 34, revelationType: 'مکی (Meccan)', virtueUrdu: 'حضرت لقمان کی اپنے بیٹے کو توحید، نماز اور اخلاق کی انمول نصیحتیں۔', virtueEnglish: 'Wisdom of Luqman and timeless parenting advice.', verses: [SurahVerseModel(number: 17, arabic: 'يَـٰبُنَىَّ أَقِمِ ٱلصَّلَوٰةَ وَأْمُرْ بِٱلْمَعْرُوفِ وَٱنْهَ عَنِ ٱلْمُنكَرِ...', urduTranslation: 'اے میرے بیٹے! نماز قائم کر، نیکی کا حکم دے اور برائی سے روک...', englishTranslation: 'O my son, establish prayer, enjoin what is right, forbid what is wrong...')]),
    SurahModel(number: 32, nameArabic: 'سُورَةُ ٱلسَّجْدَةِ', nameUrdu: 'سورۃ السجدہ', nameEnglish: 'Surah As-Sajdah', versesCount: 30, revelationType: 'مکی (Meccan)', virtueUrdu: 'نبی کریم ﷺ ہر جمعہ کی فجر اور ہر رات سونے سے پہلے اس کی تلاوت فرماتے تھے۔', virtueEnglish: 'The Prophet (PBUH) recited this every night before sleeping.', verses: [SurahVerseModel(number: 15, arabic: 'إِنَّمَا يُؤْمِنُ بِـَٔايَـٰتِنَا ٱلَّذِينَ إِذَا ذُكِّرُوا۟ بِهَا خَرُّوا۟ سُجَّدًۭا...', urduTranslation: 'ہماری آیات پر وہی لوگ ایمان لاتے ہیں کہ جب انہیں ان سے نصیحت کی جائے تو وہ سجدے میں گر پڑتے ہیں...', englishTranslation: 'Only those believe in Our verses who, when they are reminded by them, fall down in prostration...')]),
    SurahModel(number: 33, nameArabic: 'سُورَةُ ٱلْأَحْزَابِ', nameUrdu: 'سورۃ الاحزاب', nameEnglish: 'Surah Al-Ahzab', versesCount: 73, revelationType: 'مدنی (Medinan)', virtueUrdu: 'غزوہ خندق اور حضور ﷺ پر درود و سلام بھیجنے کا عظیم حکم۔', virtueEnglish: 'Contains the divine command to send blessings upon the Prophet (PBUH).', verses: [SurahVerseModel(number: 56, arabic: 'إِنَّ ٱللَّهَ وَمَلَـٰٓئِكَتَهُۥ يُصَلُّونَ عَلَى ٱلنَّبِىِّ ۚ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ صَلُّوا۟ عَلَيْهِ وَسَلِّمُوا۟ تَسْلِيمًا', urduTranslation: 'بیشک اللہ اور اس کے فرشتے نبی ﷺ پر درود بھیجتے ہیں، اے ایمان والو! تم بھی ان پر خوب درود و سلام بھیجو۔', englishTranslation: 'Indeed, Allah confers blessing upon the Prophet, and His angels. O you who have believed, ask [Allah to confer] blessing upon him and ask [Allah to grant him] peace.')]),
    SurahModel(number: 34, nameArabic: 'سُورَةُ سَبَإٍ', nameUrdu: 'سورۃ سبا', nameEnglish: 'Surah Saba', versesCount: 54, revelationType: 'مکی (Meccan)', virtueUrdu: 'قوم سبا پر نعمتوں اور ناشکری پر سزا کا عبرتناک بیان۔', virtueEnglish: 'Story of Saba and how gratitude preserves blessings.', verses: [SurahVerseModel(number: 1, arabic: 'ٱلْحَمْدُ لِلَّهِ ٱلَّذِى لَهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ...', urduTranslation: 'تمام تعریفیں اللہ ہی کے لیے ہیں جس کا ہے جو کچھ آسمانوں اور زمین میں ہے...', englishTranslation: '[All] praise is [due] to Allah, to whom belongs whatever is in the heavens and whatever is in the earth...')]),
    SurahModel(number: 35, nameArabic: 'سُورَةُ فَاطِرٍ', nameUrdu: 'سورۃ فاطر', nameEnglish: 'Surah Fatir', versesCount: 45, revelationType: 'مکی (Meccan)', virtueUrdu: 'آسمانوں اور زمین کے خالق اور فرشتوں کی تخلیق کا بیان۔', virtueEnglish: 'Highlights Allah as the Creator of angels and cosmos.', verses: [SurahVerseModel(number: 1, arabic: 'ٱلْحَمْدُ لِلَّهِ فَاطِرِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ...', urduTranslation: 'تمام تعریفیں اللہ کے لیے ہیں جو آسمانوں اور زمین کو پیدا کرنے والا ہے...', englishTranslation: '[All] praise is [due] to Allah, Creator of the heavens and the earth...')]),
    SurahModel(
      number: 36,
      nameArabic: 'سُورَةُ يس',
      nameUrdu: 'سورۃ یٰسٓ',
      nameEnglish: 'Surah Ya-Sin',
      versesCount: 83,
      revelationType: 'مکی (Meccan)',
      virtueUrdu: 'قرآن مجید کا دل ہے، روزانہ تلاوت کرنے سے گناہ معاف ہوتے ہیں اور حاجات پوری ہوتی ہیں۔',
      virtueEnglish: 'The Heart of the Quran; reading it daily brings forgiveness of sins and fulfillment of needs.',
      verses: [
        SurahVerseModel(number: 1, arabic: 'يسٓ', urduTranslation: 'یٰسٓ۔', englishTranslation: 'Ya, Seen.'),
        SurahVerseModel(number: 2, arabic: 'وَٱلْقُرْءَانِ ٱلْحَكِيمِ', urduTranslation: 'حکمت والے قرآن کی قسم۔', englishTranslation: 'By the wise Qur\'an.'),
      ],
    ),
    SurahModel(number: 37, nameArabic: 'سُورَةُ ٱلصَّـٰفَّـٰتِ', nameUrdu: 'سورۃ الصافات', nameEnglish: 'Surah As-Saffat', versesCount: 182, revelationType: 'مکی (Meccan)', virtueUrdu: 'فرشتوں کی صفوں اور حضرت ابراہیم علیہ السلام کی قربانی کا ذکر۔', virtueEnglish: 'Recounts the trial and sacrifice of Prophet Abraham.', verses: [SurahVerseModel(number: 180, arabic: 'سُبْحَـٰنَ رَبِّكَ رَبِّ ٱلْعِزَّةِ عَمَّا يَصِفُونَ', urduTranslation: 'پاک ہے آپ کا رب جو عزت کا مالک ہے، ان باتوں سے جو یہ بناتے ہیں۔', englishTranslation: 'Exalted is your Lord, the Lord of might, above what they describe.')]),
    SurahModel(number: 38, nameArabic: 'سُورَةُ صٓ', nameUrdu: 'سورۃ صٓ', nameEnglish: 'Surah Sad', versesCount: 88, revelationType: 'مکی (Meccan)', virtueUrdu: 'حضرت داؤد اور حضرت سلیمان علیہما السلام کا صبر اور اللہ سے رجوع۔', virtueEnglish: 'The devotion and repentance of David and Solomon.', verses: [SurahVerseModel(number: 29, arabic: 'كِتَـٰبٌ أَنزَلْنَـٰهُ إِلَيْكَ مُبَـٰرَكٌۭ لِّيَدَّبَّرُوٓا۟ ءَايَـٰتِهِۦ...', urduTranslation: 'یہ ایک بابرکت کتاب ہے جو ہم نے آپ کی طرف نازل کی تاکہ لوگ اس کی آیات میں غور و فکر کریں...', englishTranslation: '[This is] a blessed Book which We have revealed to you...')]),
    SurahModel(number: 39, nameArabic: 'سُورَةُ ٱلزُّمَرِ', nameUrdu: 'سورۃ الزمر', nameEnglish: 'Surah Az-Zumar', versesCount: 75, revelationType: 'مکی (Meccan)', virtueUrdu: 'اللہ کی رحمت سے کبھی مایوس نہ ہونے کا ابدی پیغام۔', virtueEnglish: 'Contains the great verse of hope for forgiveness of all sins.', verses: [SurahVerseModel(number: 53, arabic: 'قُلْ يَـٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا...', urduTranslation: 'کہہ دیجیے کہ اے میرے بندو جنہوں نے اپنی جانوں پر زیادتی کی! اللہ کی رحمت سے مایوس نہ ہو، بیشک اللہ تمام گناہ معاف فرما دیتا ہے...', englishTranslation: 'Say, "O My servants who have transgressed against themselves, do not despair of the mercy of Allah. Indeed, Allah forgives all sins...')]),
    SurahModel(number: 40, nameArabic: 'سُورَةُ غَافِرٍ', nameUrdu: 'سورۃ غافر (المؤمن)', nameEnglish: 'Surah Ghafir', versesCount: 85, revelationType: 'مکی (Meccan)', virtueUrdu: 'اللہ کا گناہ معاف کرنے اور توبہ قبول کرنے کی صفت کا بیان۔', virtueEnglish: 'Allah is the Forgiver of sins and Acceptor of repentance.', verses: [SurahVerseModel(number: 60, arabic: 'وَقَالَ رَبُّكُمُ ٱدْعُونِىٓ أَسْتَجِبْ لَكُمْ...', urduTranslation: 'اور تمہارے رب نے فرمایا کہ مجھ سے دعا کرو میں تمہاری دعا قبول کروں گا...', englishTranslation: 'And your Lord says, "Call upon Me; I will respond to you..."')]),
    SurahModel(number: 41, nameArabic: 'سُورَةُ فُصِّلَتْ', nameUrdu: 'سورۃ فصلت', nameEnglish: 'Surah Fussilat', versesCount: 54, revelationType: 'مکی (Meccan)', virtueUrdu: 'قرآن مجید کے دلائل اور ایمان پر ثابت قدم رہنے والوں کے لیے فرشتوں کی خوشخبری۔', virtueEnglish: 'Angels bring peace and glad tidings to those who stand firm on truth.', verses: [SurahVerseModel(number: 30, arabic: 'إِنَّ ٱلَّذِينَ قَالُوا۟ رَبُّنَا ٱللَّهُ ثُمَّ ٱسْتَقَـٰمُوا۟ تَتَنَزَّلُ عَلَيْهِمُ ٱلْمَلَـٰٓئِكَةُ أَلَّا تَخَافُوا۟ وَلَا تَحْزَنُوا۟...', urduTranslation: 'بیشک جن لوگوں نے کہا ہمارا رب اللہ ہے پھر اس پر ڈٹے رہے ان پر فرشتے نازل ہوتے ہیں کہ نہ ڈرو اور نہ غم کرو...', englishTranslation: 'Indeed, those who have said, "Our Lord is Allah" and then remained on a right course - the angels will descend upon them...')]),
    SurahModel(number: 42, nameArabic: 'سُورَةُ ٱلشُّورَىٰ', nameUrdu: 'سورۃ الشوریٰ', nameEnglish: 'Surah Ash-Shura', versesCount: 53, revelationType: 'مکی (Meccan)', virtueUrdu: 'باہمی مشورے اور اللہ پر توکل کی اہمیت کا بیان۔', virtueEnglish: 'Emphasizes mutual consultation and trust in divine wisdom.', verses: [SurahVerseModel(number: 38, arabic: 'وَأَمْرُهُمْ شُورَىٰ بَيْنَهُمْ...', urduTranslation: 'اور ان کے تمام کام آپس کے مشورے سے ہوتے ہیں...', englishTranslation: 'And whose affair is [determined by] consultation among themselves...')]),
    SurahModel(number: 43, nameArabic: 'سُورَةُ ٱلزُّخْرُفِ', nameUrdu: 'سورۃ الزخرف', nameEnglish: 'Surah Az-Zukhruf', versesCount: 89, revelationType: 'مکی (Meccan)', virtueUrdu: 'سواری پر بیٹھتے وقت کی دعا اور دنیاوی زینت کی حقیقت۔', virtueEnglish: 'Contains the supplication for boarding vehicles and transport.', verses: [SurahVerseModel(number: 13, arabic: 'سُبْحَـٰنَ ٱلَّذِى سَخَّرَ لَنَا هَـٰذَا وَمَا كُنَّا لَهُۥ مُقْرِنِينَ', urduTranslation: 'پاک ہے وہ ذات جس نے اس سواری کو ہمارے تابع کیا...', englishTranslation: 'Glory unto Him Who created this transportation for us...')]),
    SurahModel(number: 44, nameArabic: 'سُورَةُ ٱلدُّخَانِ', nameUrdu: 'سورۃ الدخان', nameEnglish: 'Surah Ad-Dukhan', versesCount: 59, revelationType: 'مکی (Meccan)', virtueUrdu: 'جمعہ کی شب تلاوت کرنے سے 70 ہزار فرشتے صبح تک مغفرت کی دعا کرتے ہیں۔', virtueEnglish: 'Reciter is blessed with prayers of 70,000 angels.', verses: [SurahVerseModel(number: 1, arabic: 'حمٓ', urduTranslation: 'حٰمٓ۔', englishTranslation: 'Ha, Meem.')]),
    SurahModel(number: 45, nameArabic: 'سُورَةُ ٱلْجَاثِيَةِ', nameUrdu: 'سورۃ الجاثیہ', nameEnglish: 'Surah Al-Jathiyah', versesCount: 37, revelationType: 'مکی (Meccan)', virtueUrdu: 'قیامت کے دن تمام امتوں کے زانو کے بل گرے ہونے کا منظر۔', virtueEnglish: 'Highlights the humility of all nations on Judgment Day.', verses: [SurahVerseModel(number: 1, arabic: 'حمٓ', urduTranslation: 'حٰمٓ۔', englishTranslation: 'Ha, Meem.')]),
    SurahModel(number: 46, nameArabic: 'سُورَةُ ٱلْأَحْقَافِ', nameUrdu: 'سورۃ الاحقاف', nameEnglish: 'Surah Al-Ahqaf', versesCount: 35, revelationType: 'مکی (Meccan)', virtueUrdu: 'والدین کے ساتھ حسن سلوک اور قوم عاد کے انجام کا سبق۔', virtueEnglish: 'Lessons from past nations and kindness to parents.', verses: [SurahVerseModel(number: 15, arabic: 'وَوَصَّيْنَا ٱلْإِنسَـٰنَ بِوَٰلِدَيْهِ إِحْسَـٰنًا ۖ...', urduTranslation: 'اور ہم نے انسان کو اپنے والدین کے ساتھ حسن سلوک کا حکم دیا...', englishTranslation: 'And We have enjoined upon man, to his parents, good treatment...')]),
    SurahModel(number: 47, nameArabic: 'سُورَةُ مُحَمَّدٍ', nameUrdu: 'سورۃ محمد', nameEnglish: 'Surah Muhammad', versesCount: 38, revelationType: 'مدنی (Medinan)', virtueUrdu: 'حضور اکرم ﷺ کا نام مبارک اور دین اسلام کے دفاع کا حکم۔', virtueEnglish: 'Highlights the dignity of the Prophet (PBUH) and defending faith.', verses: [SurahVerseModel(number: 7, arabic: 'يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن تَنصُرُوا۟ ٱللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ', urduTranslation: 'اے ایمان والو! اگر تم اللہ کے دین کی مدد کرو گے تو وہ تمہاری مدد کرے گا اور تمہارے قدم جما دے گا۔', englishTranslation: 'O you who have believed, if you support Allah, He will support you and plant firmly your feet.')]),
    SurahModel(number: 48, nameArabic: 'سُورَةُ ٱلْفَتْحِ', nameUrdu: 'سورۃ الفتح', nameEnglish: 'Surah Al-Fath', versesCount: 29, revelationType: 'مدنی (Medinan)', virtueUrdu: 'صلح حدیبیہ اور فتح مبین کی عظیم خوشخبری۔', virtueEnglish: 'The Surah of Clear Victory and divine reassurance.', verses: [SurahVerseModel(number: 1, arabic: 'إِنَّا فَتَحْنَا لَكَ فَتْحًۭا مُّبِينًۭا', urduTranslation: 'بیشک ہم نے آپ کو ایک روشن فتح عطا فرمائی۔', englishTranslation: 'Indeed, We have given you, [O Muhammad], a clear conquest.')]),
    SurahModel(number: 49, nameArabic: 'سُورَةُ ٱلْحُجُرَٰتِ', nameUrdu: 'سورۃ الحجرات', nameEnglish: 'Surah Al-Hujurat', versesCount: 18, revelationType: 'مدنی (Medinan)', virtueUrdu: 'اسلامی معاشرے، ادب اور اخلاق کا مکمل ضابطہ حیات۔', virtueEnglish: 'The Islamic Code of Conduct, respect, and brotherhood.', verses: [SurahVerseModel(number: 10, arabic: 'إِنَّمَا ٱلْمُؤْمِنُونَ إِخْوَةٌۭ...', urduTranslation: 'بیشک تمام مومن آپس میں بھائی بھائی ہیں...', englishTranslation: 'The believers are but brothers...')]),
    SurahModel(number: 50, nameArabic: 'سُورَةُ قٓ', nameUrdu: 'سورۃ قٓ', nameEnglish: 'Surah Qaf', versesCount: 45, revelationType: 'مکی (Meccan)', virtueUrdu: 'موت، قبر، حشر اور اللہ کی رگ جان سے بھی زیادہ قربت کا بیان۔', virtueEnglish: 'Reminds of death, resurrection, and Allah\'s closeness to man.', verses: [SurahVerseModel(number: 16, arabic: 'وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ ٱلْوَرِيدِ', urduTranslation: 'اور ہم اس کی رگ جان سے بھی زیادہ اس کے قریب ہیں۔', englishTranslation: 'And We are closer to him than [his] jugular vein.')]),
    SurahModel(number: 51, nameArabic: 'سُورَةُ ٱلذَّٰرِيَـٰتِ', nameUrdu: 'سورۃ الذاریات', nameEnglish: 'Surah Adh-Dhariyat', versesCount: 60, revelationType: 'مکی (Meccan)', virtueUrdu: 'انسان اور جنات کی تخلیق کا مقصد صرف اللہ کی عبادت ہے۔', virtueEnglish: 'Proclaims that Jinn and mankind were created solely to worship Allah.', verses: [SurahVerseModel(number: 56, arabic: 'وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ', urduTranslation: 'اور میں نے جنات اور انسانوں کو صرف اپنی عبادت کے لیے پیدا کیا ہے۔', englishTranslation: 'And I did not create the jinn and mankind except to worship Me.')]),
    SurahModel(number: 52, nameArabic: 'سُورَةُ ٱلطُّورِ', nameUrdu: 'سورۃ الطور', nameEnglish: 'Surah At-Tur', versesCount: 49, revelationType: 'مکی (Meccan)', virtueUrdu: 'کوہ طور کی قسم اور جنتیوں کی اپنے خاندانوں کے ساتھ ملاقات کا ذکر۔', virtueEnglish: 'Recounts Mount Sinai and the reunion of believers in Paradise.', verses: [SurahVerseModel(number: 1, arabic: 'وَٱلطُّورِ', urduTranslation: 'کوہ طور کی قسم۔', englishTranslation: 'By the mount,')]),
    SurahModel(number: 53, nameArabic: 'سُورَةُ ٱلنَّجْمِ', nameUrdu: 'سورۃ النجم', nameEnglish: 'Surah An-Najm', versesCount: 62, revelationType: 'مکی (Meccan)', virtueUrdu: 'معراج النبی ﷺ اور سدرۃ المنتہیٰ کا روحانی مشاہدہ۔', virtueEnglish: 'Contains the heavenly vision of the Prophet (PBUH) at the Lote Tree.', verses: [SurahVerseModel(number: 3, arabic: 'وَمَا يَنطِقُ عَنِ ٱلْهَوَىٰٓ', urduTranslation: 'اور وہ اپنی خواہش سے کوئی بات نہیں کہتے۔', englishTranslation: 'Nor does he speak from [his own] inclination.')]),
    SurahModel(number: 54, nameArabic: 'سُورَةُ ٱلْقَمَرِ', nameUrdu: 'سورۃ القمر', nameEnglish: 'Surah Al-Qamar', versesCount: 55, revelationType: 'مکی (Meccan)', virtueUrdu: 'شق القمر کا معجزہ اور قرآن کے یاد کرنے میں آسانی کا بیان۔', virtueEnglish: 'Recounts splitting of the moon and how easy Quran is to memorize.', verses: [SurahVerseModel(number: 17, arabic: 'وَلَقَدْ يَسَّرْنَا ٱلْقُرْءَانَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍۢ', urduTranslation: 'اور بیشک ہم نے قرآن کو نصیحت کے لیے آسان کر دیا تو ہے کوئی نصیحت حاصل کرنے والا؟', englishTranslation: 'And We have certainly made the Qur\'an easy for remembrance, so is there any who will remember?')]),
    SurahModel(
